26	    init() {
27	        // bckbrnr is the umbrella; each utility is a modality-named workspace
28	        // beneath it. Text ships now; vision/voice/embed are siblings later.
29	        let defaultDesk = FileManager.default.homeDirectoryForCurrentUser
