39	        self.rootDisplay = Self.collapseTilde(desk.path)
40	        self.engine = EnginePaths.discover()
41	        if let model = resolveModel() { modelName = model.lastPathComponent }
42	        let code = engineStatusCode()
43	        if code == 0 || code == 2 {
44	            isRunning = true
