59	    // MARK: lifecycle
60	
61	    func start() {
62	        do {
63	            try ensureFolders()
64	            guard let model = resolveModel() else { setStatus("Choose a model to begin"); return }
65	            guard let engine = EnginePaths.discover() else {
66	                setStatus("Engine binaries not found (set BCKBRNR_ENGINE_DIR)"); return
67	            }
68	            self.engine = engine
69	            let code = engineStatusCode()
70	            if code == 0 || code == 2 {            // ready or starting: live states only
71	                daemon = nil                       // adopt the already-running daemon
72	            } else if daemon?.isRunning != true {
73	                try startDaemon(model: model, engine: engine)
74	            }
75	            DispatchQueue.main.async {
76	                self.isRunning = true
77	                self.statusText = "Warming up…"
78	            }
79	            awaitReadiness(launched: daemon)
80	            recoverCompletedResponses()
81	        } catch {
82	            setStatus("Start failed: \(error.localizedDescription)")
83	        }
84	    }
