86	    /// Poll the engine until the model is loaded. "Ready" is the engine's
87	    /// word, not ours: exit 0 means ready, 2 means still loading, 1 means
88	    /// the daemon is gone.
89	    private func awaitReadiness(launched: Process?) {
90	        queue.async { [weak self] in
91	            guard let self else { return }
92	            let deadline = Date().addingTimeInterval(180)
93	            while Date() < deadline {
94	                switch self.engineStatusCode() {
95	                case 0:
96	                    self.setStatus("Ready")
97	                    return
98	                case 2:
99	                    break // still loading
100	                default:
101	                    if launched == nil || launched?.isRunning != true {
102	                        DispatchQueue.main.async { self.isRunning = false }
103	                        self.setStatus("Engine stopped during startup")
104	                        return
105	                    }
106	                }
107	                Thread.sleep(forTimeInterval: 1)
108	            }
109	            self.setStatus("Engine is taking unusually long to load")
110	        }
111	    }
