113	    /// Re-check whether a daemon is actually alive and flip the UI to match.
114	    /// Called when the popover opens so the prompt box only shows for a live
115	    /// daemon — you can never send a prompt into nothing.
116	    func refresh() {
117	        let code = engineStatusCode()
118	        let alive = code == 0 || code == 2
119	        DispatchQueue.main.async {
120	            self.isRunning = alive
121	            // Always refresh the label: starting → ready flips the text even
122	            // when the running boolean hasn't changed.
123	            self.statusText = alive ? (code == 0 ? "Ready" : "Warming up…") : Self.restingHint
124	        }
125	        if alive { recoverCompletedResponses() }
126	    }
