128	    /// On app quit, shut down the daemon bound to this utility workspace.
129	    /// bckbrnr owns this workspace; leaving it headless is more surprising than
130	    /// stopping it. The engine identifies and stops its own process — we never
131	    /// signal a pid ourselves.
132	    func terminateWorkspaceDaemon() {
133	        engineStop()
134	        daemon = nil
135	    }
