155	    func submit(_ text: String) {
156	        // Never send into a dead workspace: require a live daemon, not just
157	        // that Start was pressed at some point. (Starting counts — the queue
158	        // holds the prompt until the model finishes loading.) Only 0 and 2
159	        // are live states; any other exit code is not a daemon.
160	        let code = engineStatusCode()
161	        let alive = code == 0 || code == 2
162	        guard alive, let engine else { refresh(); return }
163	        setStatus("Working…")
164	        queue.async { [weak self] in
165	            guard let self else { return }
166	            let stem = Naming.uniqueStem(Naming.deriveStem(from: text), in: self.promptDir, ext: "txt")
167	            let promptFile = self.promptDir.appendingPathComponent("\(stem).txt")
168	            let responseFile = self.responseDir.appendingPathComponent("\(stem).txt")
169	            do {
170	                try text.write(to: promptFile, atomically: true, encoding: .utf8)
171	                let jobId = try self.runProcess(engine.wrk, arguments: [self.workspace.path, "-"], input: text)
172	                    .trimmingCharacters(in: .whitespacesAndNewlines)
173	                let result = try self.runProcess(engine.flw, arguments: [self.workspace.path, "-w", jobId])
174	                try result.write(to: responseFile, atomically: true, encoding: .utf8)
175	                self.setStatus("Ready")
176	                self.notify(title: "bckbrnr — your answer is ready", body: stem, path: responseFile.path)
177	            } catch {
178	                // Failure is durable too: leave a readable artifact beside
179	                // where the answer would have been.
180	                let errorFile = self.responseDir.appendingPathComponent("\(stem).error.txt")
181	                let body = """
182	                bckbrnr couldn’t finish this prompt.
183	
184	                PROMPT:
185	                \(text)
186	
187	                ERROR:
188	                \(error.localizedDescription)
189	                """
190	                try? body.write(to: errorFile, atomically: true, encoding: .utf8)
191	                self.setStatus("Ready")
192	                self.notify(title: "bckbrnr — couldn’t finish", body: stem, path: errorFile.path)
193	            }
194	        }
195	    }
196	
197	    private func recoverCompletedResponses() {
198	        queue.async { [weak self] in
199	            guard let self else { return }
200	            try? self.ensureFolders()
201	            // Success and failure are both durable: backfill answers from
202	            // completed jobs and error artifacts from failed ones.
203	            self.reconcile(subdir: "output", source: "result.txt",
204	                           ext: ".txt", title: "bckbrnr — your answer is ready")
205	            self.reconcile(subdir: "failed", source: "error.txt",
206	                           ext: ".error.txt", title: "bckbrnr — couldn’t finish")
207	        }
208	    }
