210	    /// Mirror a finished nrvna job into the user-facing response folder, once.
211	    /// Runs on the work queue.
212	    private func reconcile(subdir: String, source: String, ext: String, title: String) {
213	        let dir = workspace.appendingPathComponent(subdir, isDirectory: true)
214	        guard let jobs = try? FileManager.default.contentsOfDirectory(
215	            at: dir, includingPropertiesForKeys: [.isDirectoryKey], options: [.skipsHiddenFiles]
216	        ) else { return }
217	        for job in jobs {
218	            guard (try? job.resourceValues(forKeys: [.isDirectoryKey]))?.isDirectory == true,
219	                  let prompt = try? String(contentsOf: job.appendingPathComponent("prompt.txt")),
220	                  let content = try? String(contentsOf: job.appendingPathComponent(source))
221	            else { continue }
222	            let base = recoveryStem(for: prompt, ext: ext)
223	            let target = responseDir.appendingPathComponent("\(base)\(ext)")
224	            guard !FileManager.default.fileExists(atPath: target.path) else { continue }
225	            try? content.write(to: target, atomically: true, encoding: .utf8)
226	            notify(title: title, body: base, path: target.path)
227	        }
228	    }
