230	    /// Submission already chose a collision-safe prompt filename. Recover that
231	    /// same identity instead of deriving the unsuffixed first-line stem again.
232	    private func recoveryStem(for prompt: String, ext: String) -> String {
233	        let fallback = Naming.deriveStem(from: prompt)
234	        guard let files = try? FileManager.default.contentsOfDirectory(
235	            at: promptDir, includingPropertiesForKeys: nil, options: [.skipsHiddenFiles]
236	        ) else { return fallback }
237	        for file in files.sorted(by: { $0.lastPathComponent < $1.lastPathComponent })
238	        where file.pathExtension == "txt" {
239	            guard let saved = try? String(contentsOf: file), saved == prompt else { continue }
240	            let stem = file.deletingPathExtension().lastPathComponent
241	            let target = responseDir.appendingPathComponent("\(stem)\(ext)")
242	            if !FileManager.default.fileExists(atPath: target.path) { return stem }
243	        }
244	        return fallback
245	    }
