279	    func setRoot(_ raw: String) {
280	        guard !isRunning else { setStatus("Stop before changing the root"); return }
281	        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
282	        guard !trimmed.isEmpty else { rootDisplay = Self.collapseTilde(desk.path); return }
283	        let expanded = NSString(string: trimmed).expandingTildeInPath
284	        applyDesk(URL(fileURLWithPath: expanded, isDirectory: true))
