311	    private func resolveModel() -> URL? {
312	        let env = ProcessInfo.processInfo.environment
313	        let candidates = [env["BCKBRNR_TEXT_MODEL"], defaults.string(forKey: "textModelPath")].compactMap { $0 }
314	        for path in candidates {
315	            let url = URL(fileURLWithPath: NSString(string: path).expandingTildeInPath)
