321	    private func startDaemon(model: URL, engine: EnginePaths) throws {
322	        let process = Process()
323	        process.executableURL = engine.nrvnad
324	        process.arguments = [model.path, workspace.path, "-w", "1"]
325	        // Conservative defaults for a non-technical, single-GPU machine:
326	        // CPU only (0 GPU layers) avoids the discrete-GPU overflow that yields
327	        // gibberish; low temp + thinking-off keep small models terse and on-task;
328	        // modest predict/ctx bound latency and VRAM. Any of these can be
329	        // overridden by exporting the same NRVNA_* var before launch.
330	        process.environment = ProcessInfo.processInfo.environment.merging([
331	            "NRVNA_GPU_LAYERS": "0",
332	            "NRVNA_TEMP": "0.3",
333	            "NRVNA_PREDICT": "1024",
334	            "NRVNA_MAX_CTX": "4096",
335	            "NRVNA_THINKING": "0"
336	        ]) { _, new in new }
337	        try process.run()
338	        daemon = process
339	    }
