341	    /// Exit codes from `nrvnad status`: 0 ready, 2 starting, 1 not running.
342	    /// The engine owns lifecycle truth; bckbrnr never reads pidfiles or
343	    /// signals processes itself.
344	    private func engineStatusCode() -> Int32 {
345	        guard let engine = engine ?? EnginePaths.discover() else { return 1 }
346	        let process = Process()
347	        process.executableURL = engine.nrvnad
348	        process.arguments = ["status", workspace.path]
349	        process.standardOutput = Pipe()
350	        process.standardError = Pipe()
351	        guard (try? process.run()) != nil else { return 1 }
352	        process.waitUntilExit()
353	        return process.terminationStatus
354	    }
355	
356	    /// Graceful stop, delegated to the engine (short timeout: this runs on
357	    /// app-quit, where macOS gives us limited time).
358	    private func engineStop() {
359	        guard let engine = engine ?? EnginePaths.discover() else { return }
360	        let process = Process()
361	        process.executableURL = engine.nrvnad
362	        process.arguments = ["stop", workspace.path, "--timeout", "5"]
363	        process.standardOutput = Pipe()
364	        process.standardError = Pipe()
365	        try? process.run()
366	        process.waitUntilExit()
367	    }
368	
369	    private func runProcess(_ executable: URL, arguments: [String], input: String? = nil) throws -> String {
370	        let process = Process(); let stdout = Pipe(); let stderr = Pipe(); let stdin = Pipe()
371	        process.executableURL = executable
372	        process.arguments = arguments
373	        process.standardOutput = stdout
374	        process.standardError = stderr
375	        if input != nil { process.standardInput = stdin }
376	        try process.run()
377	
378	        // Drain both pipes while the child runs. Waiting first can deadlock if
379	        // either pipe fills and the child blocks before it can exit.
380	        let stdoutBox = ProcessOutputBox()
381	        let stderrBox = ProcessOutputBox()
382	        let readers = DispatchGroup()
383	        readers.enter()
384	        DispatchQueue.global(qos: .utility).async {
385	            stdoutBox.data = stdout.fileHandleForReading.readDataToEndOfFile()
386	            readers.leave()
387	        }
388	        readers.enter()
389	        DispatchQueue.global(qos: .utility).async {
390	            stderrBox.data = stderr.fileHandleForReading.readDataToEndOfFile()
391	            readers.leave()
392	        }
393	        if let input {
394	            stdin.fileHandleForWriting.write(input.data(using: .utf8) ?? Data())
395	            try? stdin.fileHandleForWriting.close()
396	        }
397	        process.waitUntilExit()
398	        readers.wait()
399	        let output = String(data: stdoutBox.data, encoding: .utf8) ?? ""
400	        let errOut = String(data: stderrBox.data, encoding: .utf8) ?? ""
401	        guard process.terminationStatus == 0 else {
402	            throw NSError(domain: "bckbrnr", code: Int(process.terminationStatus),
403	                          userInfo: [NSLocalizedDescriptionKey: errOut.isEmpty ? output : errOut])
404	        }
405	        return output
406	    }
