3	/// Turns a prompt into a friendly, collision-safe filename stem.
4	/// The user never names anything — bckbrnr derives it from what they typed.
5	enum Naming {
6	    /// First non-empty line, cleaned of path-illegal characters,
7	    /// whitespace-collapsed, capped at 40 characters. Empty → "prompt".
8	    static func deriveStem(from prompt: String) -> String {
9	        let firstLine = prompt
10	            .split(whereSeparator: \.isNewline)
11	            .map { $0.trimmingCharacters(in: .whitespaces) }
12	            .first(where: { !$0.isEmpty }) ?? ""
13	
14	        var cleaned = firstLine
15	        for bad in ["/", ":", "\\"] {
16	            cleaned = cleaned.replacingOccurrences(of: bad, with: " ")
17	        }
18	        cleaned = cleaned
19	            .components(separatedBy: .whitespacesAndNewlines)
20	            .filter { !$0.isEmpty }
21	            .joined(separator: " ")
22	
23	        if cleaned.count > 40 {
24	            let capped = String(cleaned.prefix(40))
25	            // Cut back to the last whole word so we don't end mid-word.
26	            if let lastSpace = capped.lastIndex(of: " ") {
27	                cleaned = String(capped[..<lastSpace])
28	            } else {
29	                cleaned = capped
30	            }
31	            cleaned = cleaned.trimmingCharacters(in: .whitespaces)
32	        }
33	        return cleaned.isEmpty ? "prompt" : cleaned
34	    }
35	
36	    /// A stem unique within `dir` for `ext`, appending -2, -3… if taken.
37	    /// Never overwrites an existing file (durability).
38	    static func uniqueStem(_ base: String, in dir: URL, ext: String) -> String {
39	        let fm = FileManager.default
40	        var candidate = base
41	        var n = 2
42	        while fm.fileExists(atPath: dir.appendingPathComponent("\(candidate).\(ext)").path) {
43	            candidate = "\(base)-\(n)"
44	            n += 1
45	        }
46	        return candidate
47	    }
48	}
